package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.*;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Cleaner_clean_TriageGen2Test {

    private Cleaner cleaner;

    @Before
    public void setUp() {
        cleaner = new Cleaner(org.jsoup.safety.Whitelist.basic());
    }

    @Test
    public void testClean_NullDocument_ShouldThrowNullPointerException() {
        assertThrows(NullPointerException.class, () -> cleaner.clean(null));
    }

    @Test
    public void testClean_EmptyDocument_ShouldReturnEmptyDocument() {
        Document dirtyDocument = Document.parse("");
        Document cleanDocument = cleaner.clean(dirtyDocument);
        assertNotNull(cleanDocument);
        assertEquals(0, cleanDocument.select("*").size());
    }

    @Test
    public void testClean_ContainsSafeTags_ShouldReturnSameDocumentStructure() {
        String html = "<html><body><p>Safe text</p></body></html>";
        Document dirtyDocument = Document.parse(html);
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        assertEquals("Safe text", cleanDocument.body().text());
        assertEquals(1, cleanDocument.select("p").size());
    }

    @Test
    public void testClean_ContainsUnsafeTags_ShouldRemoveThem() {
        String html = "<html><body><script>alert('xss');</script><p>Safe text</p></body></html>";
        Document dirtyDocument = Document.parse(html);
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        assertEquals("Safe text", cleanDocument.body().text());
        assertEquals(1, cleanDocument.select("p").size());
        assertNull(cleanDocument.select("script").first());
    }

    @Test
    public void testClean_WithBaseUri_ShouldPreserveBaseUri() {
        String html = "<html><body><p>Safe text</p></body></html>";
        Document dirtyDocument = Document.parse(html, "http://example.com");
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        assertEquals("http://example.com", cleanDocument.baseUri());
    }

    @Test
    public void testClean_WithAttributes_ShouldPreserveSafeAttributes() {
        String html = "<html><body><p title='safe'>Safe text</p></body></html>";
        Document dirtyDocument = Document.parse(html);
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        assertEquals("safe", cleanDocument.select("p").first().attr("title"));
    }

    @Test
    public void testClean_WithUnsafeAttributes_ShouldRemoveThem() {
        String html = "<html><body><p style='color:red;'>Unsafe text</p></body></html>";
        Document dirtyDocument = Document.parse(html);
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        assertNull(cleanDocument.select("p").first().attr("style"));
    }

    @Test
    public void testClean_WithNestedTags_ShouldCleanInnerTags() {
        String html = "<div><p>Safe <b>bold</b> text</p></div>";
        Document dirtyDocument = Document.parse(html);
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        assertEquals("Safe bold text", cleanDocument.body().text());
        assertEquals(1, cleanDocument.select("p").size());
        assertEquals(1, cleanDocument.select("b").size());
    }

    @Test
    public void testClean_WithMixedContent_ShouldCleanProperly() {
        String html = "<html><body><script>alert('xss');</script><p>Safe <i>italic</i> text</p></body></html>";
        Document dirtyDocument = Document.parse(html);
        Document cleanDocument = cleaner.clean(dirtyDocument);

        assertNotNull(cleanDocument);
        assertEquals("Safe italic text", cleanDocument.body().text());
        assertEquals(1, cleanDocument.select("p").size());
        assertEquals(1, cleanDocument.select("i").size());
        assertNull(cleanDocument.select("script").first());
    }
}
